window.Components=(()=>{
 const {e,icon,button,badge,field,input,select}=UI;
 const binding=c=>`${Cousins.getDevice(c.device)?.name||'Select device'} / ${(c.channels||[]).map(id=>Cousins.channelInfo(c.device,id)?.name||id).join(', ')}${(c.extraStreams||[]).map(s=>' + '+(Cousins.getDevice(s.device)?.name||s.device)+' / '+(Cousins.channelInfo(s.device,s.channel)?.name||s.channel)).join('')}`;
 function body(c,run,editing){
  const device=Cousins.getDevice(c.device),channel=Cousins.channelInfo(c.device,c.channels?.[0]),unit=channel?.unit||'',mode=c.process==='linear'?'Derived':c.process&&c.process!=='raw'?'Profile':'Raw';
  if(c.kind==='chart')return `<div class="component-meta"><span class="source-tag ${mode==='Derived'?'derived':''}">${mode}</span>${UI.name(binding(c))}</div><div class="chart" data-chart="${e(JSON.stringify(c))}" role="img" aria-label="${e(c.title)}; ${e(unit)} over time"></div>`;
  if(c.kind==='numeric'){if(!channel||channel.shape.startsWith('Vector'))return '<p class="tile-note">Select a scalar channel in Data.</p>';let value=Cousins.signal(run?Runtime.position(run):84,(c.channels||[])[0]==='mz44'?1:0);if(c.process==='linear')value=value*(c.gain===undefined?1:Number(c.gain))+(Number(c.offset)||0);return `<div class="metric" style="--metric-color:${e(/^#[0-9a-f]{6}$/i.test(c.colorHex||'')?c.colorHex:'var(--accent)')}"><span class="metric-number"><span data-metric="${e(JSON.stringify(c))}">${value.toFixed(2)}</span><span class="metric-unit">${e(unit)}</span></span><div class="metric-caption"><span class="metric-symbol">${icon('chart')}</span>${UI.name(channel?.name||'No channel')}<span class="source-tag">${mode}</span></div></div>`;}
  if(c.kind==='control'){
   const state=run?.deviceStates?.[c.device],value=state?.draft??state?.applied??device?.applied??0;
   return `<div class="control-body">${!device?'<p>Select a device in Data.</p>':`${field(device.parameter,`<div class="unit-input">${input('parameter',value,'number',`min="${device.min}" max="${device.max}" step="${device.step}" data-parameter="${e(c.device)}" ${run?.acquisition==='Completed'?'disabled':''}`)}<span>${e(device.unit)}</span></div>`,`${device.min}–${device.max} ${device.unit}`)}${device.unit==='%'?`<input aria-label="LED output" type="range" min="0" max="100" value="${value}" data-parameter="${e(c.device)}">`:''}<div class="applied-line"><span>Applied <strong>${state?.applied??device.applied} ${e(device.unit)}</strong></span>${button('Apply','apply-parameter',{id:c.device,disabled:editing||!run||run.acquisition==='Completed'})}</div><div class="command-actions">${(c.controlScope==='group'?['Start group','Stop group']:device.commands).map(cmd=>`<button class="btn ${cmd==='Stop'||cmd==='Disable'?'':'primary'}" data-action="${c.controlScope==='group'?'group-command':'command'}" data-command="${e(cmd)}" data-id="${e(device.id)}" ${editing||!run||run.acquisition==='Completed'?'disabled':''}>${icon(cmd==='Stop'||cmd==='Disable'?'stop':'play')}${e(cmd)}</button>`).join('')}</div>${state?badge(state.command):'<span class="quiet-label">Commands available during acquisition</span>'}`}</div>`;
  }
  if(c.kind==='inputs')return `<div class="form-grid">${(c.fields||[]).map(f=>`<div class="form-field ${f.type==='boolean'?'boolean-field':''}" style="--field-span:${Math.min(12,Number(f.span)||6)}">${f.type==='boolean'?`<label class="check-row"><input type="checkbox" data-value-field="${e(f.id)}" data-component="${c.id}" ${f.value?'checked':''}><span>${e(f.label)}</span></label>`:field(f.label,f.type==='select'?select(f.id,f.value,f.options||[],`data-value-field="${e(f.id)}" data-component="${c.id}"`):`<div class="unit-input">${input(f.id,f.value,f.type==='number'?'number':'text',`data-value-field="${e(f.id)}" data-component="${c.id}" ${f.type==='number'?`min="${f.min??''}" max="${f.max??''}" step="${f.step||'any'}"`:''}`)}${f.unit?`<span>${e(f.unit)}</span>`:''}</div>`)}</div>`).join('')}</div>`;
  if(c.kind==='calibration')return `<div class="table-wrap"><table class="cal-table"><thead><tr><th>Reference (${e(unit)})</th><th>Measured (${e(unit)})</th><th></th></tr></thead><tbody>${(c.rows||[]).map((r,i)=>`<tr><td><input aria-label="Reference row ${i+1}" type="number" step="any" value="${e(r[0])}" data-cal="${c.id}" data-row="${i}" data-col="0"></td><td><input aria-label="Measured row ${i+1}" type="number" step="any" value="${e(r[1])}" data-cal="${c.id}" data-row="${i}" data-col="1"></td><td>${button('Remove row','cal-remove',{id:c.id+':'+i,icon:'close',iconOnly:true})}</td></tr>`).join('')}</tbody></table></div><div class="tile-foot">${button('Add row','cal-add',{id:c.id,icon:'plus',quiet:true})}<span class="quiet-label">Reference → measured</span></div>`;
  if(c.kind==='results')return `<div class="table-wrap"><table><thead><tr><th>Profile</th><th>Result</th><th>Calculation</th></tr></thead><tbody><tr><td>${e(c.profile||'Selected profile')}</td><td>—</td><td><span class="badge warn">Formula required</span></td></tr></tbody></table></div><p class="tile-note">${e(c.profile||'Profile')} calculations are not defined.</p>`;
  return '';
 }
 function grid(items,{editing=false,selected='',run=null,parent='root'}={}){
  return `<div class="bento-grid ${editing?'editable':''}" data-grid="${e(parent)}" style="--rows:${Math.max(4,...items.map(c=>c.y+c.h))}">${items.map(c=>`<section class="bento-tile ${c.kind==='group'?'group-tile':''} ${selected===c.id?'selected':''}" data-component-id="${c.id}" style="grid-column:${c.x+1}/span ${c.w};grid-row:${c.y+1}/span ${c.h}"><header class="tile-header"><div class="tile-title">${editing?`<button class="drag-handle" draggable="true" data-drag="${c.id}" aria-label="Move ${e(c.title)}">${icon('grip')}</button>`:''}<h3>${e(c.title)}</h3></div>${editing?button('Configure '+c.title,'select-component',{id:c.id,icon:'sliders',iconOnly:true}):''}</header>${c.kind==='group'?grid(c.children||[],{editing,selected,run,parent:c.id}):body(c,run,editing)}${editing?`<button class="resize-handle" data-resize="${c.id}" aria-label="Resize ${e(c.title)}">${icon('resize')}</button>`:''}</section>`).join('')}${!items.length?`<div class="grid-empty"><span>Drop components here</span>${editing?button('Add component','picker',{icon:'plus'}):''}</div>`:''}</div>`;
 }
 return {grid,body,binding};
})();
